import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

/// REVIEW SCRATCH — verifies resolveEffectiveCliArgs edge combinations for
/// pr-1975. Deleted after the review run; not part of the suite.
void main() {
  final customOnly = CliConfig(
    customProviders: [
      CustomProviderEntry(
        name: 'z.ai',
        apiType: 'openai',
        baseUrl: 'https://api.z.ai/api/coding/paas/v4',
        modelId: 'glm-5.3-flash',
        keyName: 'FA_KEY_API_Z_AI',
      ),
    ],
  );

  test('explicit --provider WITHOUT --model/--base-url + custom providers',
      () {
    final resolved = resolveEffectiveCliArgs(
      const CliArgs(provider: 'google', providerExplicit: true),
      customOnly,
      env: const {},
    );
    // What triple actually boots?
    // ignore: avoid_print
    print('provider=${resolved.provider} '
        'model=${resolved.args.model} '
        'baseUrl=${resolved.args.baseUrl}');
  });

  test('FA_PROVIDER_* preconfig beats the custom default', () {
    final resolved = resolveEffectiveCliArgs(
      const CliArgs(),
      customOnly,
      env: const {
        'FA_PROVIDER_TYPE': 'anthropic',
        'FA_PROVIDER_NAME': 'claude-x',
        'FA_PROVIDER_CONFIG':
            '{"baseUrl":"https://example.com","model":"claude-x-1"}',
      },
    );
    // ignore: avoid_print
    print('preconfig: provider=${resolved.provider} '
        'model=${resolved.args.model} '
        'baseUrl=${resolved.args.baseUrl} '
        'preconfig=${resolved.faPreconfig != null}');
  });

  test('custom entry with unknown apiType is skipped, next entry wins', () {
    final resolved = resolveEffectiveCliArgs(
      const CliArgs(),
      CliConfig(
        customProviders: [
          CustomProviderEntry(
            name: 'ghost',
            apiType: 'no-such-type',
            baseUrl: 'https://ghost.example/v1',
            modelId: 'ghost-model',
          ),
          CustomProviderEntry(
            name: 'real',
            apiType: 'openai',
            baseUrl: 'https://real.example/v1',
            modelId: 'real-model',
          ),
        ],
      ),
      env: const {},
    );
    // ignore: avoid_print
    print('skip-unknown: provider=${resolved.provider} '
        'model=${resolved.args.model} baseUrl=${resolved.args.baseUrl}');
  });

  test('factory-triple guard: hand-edited whitespace in model slot', () {
    final resolved = resolveEffectiveCliArgs(
      const CliArgs(),
      CliConfig(
        modelId: 'openai/gpt-4o-mini ',
        customProviders: customOnly.customProviders,
      ),
      env: const {},
    );
    // ignore: avoid_print
    print('whitespace-model: provider=${resolved.provider} '
        'model="${resolved.args.model}"');
  });
}

